"use strict";
// Plain JavaScript without declarations.
function point(x, y) {
  return { x: x, y: y };
}
function centroid(points) {
  if (points.length === 0) return null;
  var sx = 0;
  var sy = 0;
  for (var i = 0; i < points.length; i++) {
    sx += points[i].x;
    sy += points[i].y;
  }
  return point(sx / points.length, sy / points.length);
}
exports.point = point;
exports.centroid = centroid;
